public static boolean enthaelt(BinTree b, int x) {
    if (b.isEmpty()) {
        return false;
    }
    int wert = (Integer) b.getItem();
    if (wert == x) {
        return true;
    }
    return enthaelt(b.getLeft(), x) || enthaelt(b.getRight(), x);
}

public static String levelorder(BinTree b) {
    String text = "";
    Queue q = new Queue();
    if (!b.isEmpty()) {
        q.enqueue(b);
    }   // → Tabellenzeile (Startwerte)
    while (!q.isEmpty()) {
        BinTree k = (BinTree) q.dequeue();
        text = text + k.getItem() + " ";
        if (!k.getLeft().isEmpty()) {
            q.enqueue(k.getLeft());
        }
        if (!k.getRight().isEmpty()) {
            q.enqueue(k.getRight());
        }   // → Tabellenzeile
    }
    return text;
}

public static String levelorder(BinTree b) {
    String text = "";
    Queue q = new Queue();
    q.enqueue(b);
    while (!q.isEmpty()) {
        BinTree k = (BinTree) q.dequeue();
        text = text + k.getItem() + " ";
        q.enqueue(k.getLeft());
        q.enqueue(k.getRight());
    }
    return text;
}

public static String raetsel(BinTree b) {
    String text = "";
    Stack s = new Stack();
    if (!b.isEmpty()) {
        s.push(b);
    }
    while (!s.isEmpty()) {
        BinTree k = (BinTree) s.pop();
        text = text + k.getItem() + " ";
        if (!k.getLeft().isEmpty()) {
            s.push(k.getLeft());
        }
        if (!k.getRight().isEmpty()) {
            s.push(k.getRight());
        }
    }
    return text;
}

